using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=fake==",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF9 breaking change: The Cosmos provider now uses "$type" as the
            // discriminator property name by default instead of "Discriminator".
            // For existing documents that already store "Discriminator", you must
            // explicitly configure the old property name to avoid runtime failures.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

class CosmosQueryService
{
    // EF9 breaking change: Synchronous I/O on the Cosmos DB provider now throws
    // by default. All queries must use async methods (ToListAsync, FirstAsync, etc.)
    // If you absolutely cannot go async, opt back in via:
    //   optionsBuilder.UseCosmos(..., o => o.AllowSynchronousIO())
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products
            .Where(p => p.Category == "Books")
            .ToListAsync();
    }
}

